 d.add_page_break();d.add_heading('Supplementary information',level=1);d.add_paragraph(orig[173]+' Supplementary Figures S1-S3 provide complete adjacent-arm transitions, LD-dependent simulation rates and repeated-release disease credible-set stability.')
 name='Manuscript_AuthorReview_InlineFigures.docx' if inline else 'Manuscript_ExpertRebuilt.docx';d.save(O/'01_Manuscript'/name)
 return d
